import time

class AlphaBetaSearch(_Depth_GomokuAI):
    """Deadline adapter only; the original search implementation is inherited."""
    absolute_deadline = float('inf')

    def _check_time(self):
        self.deadline = min(self.deadline, self.absolute_deadline)
        super()._check_time()

class MCTSSearch(_MonteCarlo_GomokuAI):
    absolute_deadline = float('inf')

    def _check_time(self):
        self.deadline = min(self.deadline, self.absolute_deadline)
        super()._check_time()
NAME = 'Adaptive Search'
DEFAULT_THRESHOLD = 37
DIRECTIONS = ((0, 1), (1, 0), (1, 1), (1, -1))

def winning_placement(board, move, player, k):
    n = len(board)
    r, c = move
    for dr, dc in DIRECTIONS:
        total = 1
        for sign in (-1, 1):
            rr, cc = (r + sign * dr, c + sign * dc)
            while 0 <= rr < n and 0 <= cc < n and (board[rr][cc] == player):
                total += 1
                if total >= k:
                    return True
                rr, cc = (rr + sign * dr, cc + sign * dc)
        if total >= k:
            return True
    return False

def candidate_moves(board, empties=None, deadline=float('inf')):
    """Radius-two frontier BEFORE either engine's top-width pruning."""
    n = len(board)
    if empties is None:
        empties = [(r, c) for r in range(n) for c in range(n) if not board[r][c]]
    if len(empties) == n * n:
        return [(n // 2, n // 2)]
    result = []
    for r, c in empties:
        if time.perf_counter() >= deadline:
            raise TimeoutError('candidate deadline')
        if any((board[rr][cc] for rr in range(max(0, r - 2), min(n, r + 3)) for cc in range(max(0, c - 2), min(n, c + 3)))):
            result.append((r, c))
    return result or empties

class SearchSelector:

    def __init__(self, threshold=DEFAULT_THRESHOLD):
        self.selector_threshold = threshold
        self.low_branch_threshold = 20
        self.depth_target = 8
        self.late_phase = 0.72

    def choose(self, board, candidate_moves, time_limit, metadata=None):
        count = len(candidate_moves)
        phase = float((metadata or {}).get('game_phase', 0.0))
        previous = (metadata or {}).get('previous_ab_stats') or {}
        depth = int(previous.get('completed_depth', previous.get('depth', 0)) or 0)
        interrupted = bool(previous.get('interrupted', False))
        recent = 0 < int((metadata or {}).get('move_number', 0)) - int(previous.get('move_number', -1000)) <= 4
        comparable = previous.get('candidate_count', 0) >= count and time_limit >= previous.get('search_time', 0) * 0.9
        if count <= min(self.low_branch_threshold, self.selector_threshold):
            if recent and comparable and interrupted and (0 < depth < self.depth_target):
                return 'mcts'
            return 'alphabeta'
        budget_comparable = time_limit >= previous.get('search_time', 0) * 0.9
        if phase >= self.late_phase and count <= self.selector_threshold and budget_comparable and recent and (depth >= self.depth_target):
            return 'alphabeta'
        return 'mcts'

